// A customer reports a problem. PURE -- nothing here reads or writes state.
//
// THE WORLD CONTROLLER DECIDES THE EVENT HAPPENED. No model is asked whether a customer has a
// problem, which customer it is, what is wrong, or how badly. All of that is a seeded draw over
// the company's own categories, so the business event exists as structured facts first.
//
// THE EMAIL IS RENDERED FROM THOSE FACTS, deterministically, from fragment pools -- the same
// approach src/seed/activity.ts already takes and says why: "Prose is composed from fragment
// pools rather than generated by an LLM. That keeps the manifest byte-stable for free, keeps
// spend at zero, and is adequate for short, ordinary language." A customer's two-line problem
// report is exactly that case. Replay therefore never asks a model to reproduce anything, and
// the rendered mail is persisted anyway so a later renderer change cannot rewrite history.

import { SUPPORT_CATEGORIES, type SupportSeverity } from "../charter/charter.ts";
import { messageIdFor } from "../seed/gmailMime.ts";
// From ../seed/addresses.ts, which imports nothing, so spelling one address costs this module no
// dependencies at all.
import { customerDomain, localPart } from "../seed/addresses.ts";
import type { Rng } from "../seed/rng.ts";
import type { CrmContact, CrmWorld } from "../support/customers.ts";
import { allLivingCompanies, type LivingCrmState } from "./livingCrmState.ts";
import { INCIDENT_CAUSED_SHARE } from "./productIncident.ts";
import { openRequestCountFor, type LivingInboundEmail, type LivingSupportState } from "./livingSupportState.ts";

/**
 * Meridian's shared support inbox.
 *
 * The company's support policy establishes it as a fact about how support works -- "Support has
 * been run from shared judgement and a shared inbox since we started" -- so the address is a
 * derived detail rather than an invention. It uses the internal reserved domain for the same
 * reason every other synthetic address does: the sandbox domain policy forbids asserting any
 * registrable domain as a mail origin. Every address in this repository therefore ends in the
 * reserved `.invalid` TLD (RFC 2606), which can never be registered and never resolves.
 */
export const SUPPORT_INBOX = "support@meridianworks.invalid";

/**
 * How many requests one account may have open at once.
 *
 * Not a business rule, a realism guard: without it the seeded draw will eventually pile six open
 * requests on one account while eighty-four others have none, which reads as a generator artefact
 * rather than as a support queue. Two is enough to allow a genuinely troubled account.
 */
export const MAX_OPEN_PER_ACCOUNT = 2;

export interface SupportRequestPlan {
  companyId: string;
  companyName: string;
  contactId: string;
  contactName: string;
  contactEmail: string;
  category: string;
  severity: SupportSeverity;
  problem: string;
  subject: string;
  body: string;
  /**
   * The incident that caused this request, when one did. Null for an independent customer issue.
   *
   * HIDDEN WORLD CONTROLLER TRUTH. It sits beside `problem`, `category` and `severity`, which are
   * already the Controller's structured statement of what went wrong and are already withheld from
   * whatever answers a request: an injected processor is handed the rendered email, the policy and
   * the account, and none of these. So this field is not a new class of
   * secret in a new place; it is one more fact in the same place, under the same boundary.
   *
   * It is the ONLY link between a customer's email and the fault behind it, and it exists so the
   * simulation can be audited -- "did this request come from the recurring-jobs incident" has to be
   * answerable without guessing from the category. tests/productIncidents.test.ts asserts it cannot
   * reach the ThreadMessage, the agent's prompt, a decision-record request or the customer's reply.
   */
  causedByIncidentId: string | null;
}

/**
 * An active incident, as the support planner needs to see it.
 *
 * A NARROW VIEW, not the stored incident. The planner needs the capability (which fixes the symptom
 * the customer reports), the affected accounts, and the id to record the attribution. It does not
 * need, and is not given, the owner, the planned resolution instant or the rest of the record.
 */
export interface CausingIncident {
  incidentId: string;
  capability: string;
  affectedCompanyIds: readonly string[];
}

// --- the fragment pools --------------------------------------------------------------
//
// One subject, one problem sentence and one body opener per category. Each is written in a
// customer's voice: what they see, what it is stopping, no diagnosis and no Meridian vocabulary.
// A customer does not know the category name, so none of these text fragments contains it.

interface CategoryCopy {
  subject: readonly string[];
  /** The factual problem, which is the structured fact the support employee works from. */
  problem: readonly string[];
  /** What the customer adds after the problem. Kept short, as a real first email is. */
  detail: readonly string[];
}

