/** Every category the copy pools cover. Asserted against the charter's set in tests. */
export const COPY_CATEGORIES: readonly string[] = Object.freeze(Object.keys(COPY));

/**
 * Accounts that can raise a support request right now.
 *
 * CUSTOMERS ONLY. The frozen world supports this directly: `status` is customer, prospect or
 * churned, and support is for people who have the product. A prospect's questions go to the AE
 * working the deal, which is the sales pipeline, not the support inbox. Nothing in the frozen
 * data shows a prospect contacting support.
 *
 * Read from the RESOLVED view, so a prospect that a living closed-won deal converted becomes
 * eligible naturally, with no list of frozen customers anywhere.
 */
export function eligibleSupportAccounts(
  world: CrmWorld,
  crm: LivingCrmState | null,
  support: LivingSupportState | null,
): { companyId: string; companyName: string }[] {
  const withContact = new Set(world.contacts.map((c) => c.companyMeridianId));
  return allLivingCompanies(world, crm)
    .filter((c) => c.status === "customer")
    .filter((c) => withContact.has(c.meridianId))
    .filter((c) => openRequestCountFor(support, c.meridianId) < MAX_OPEN_PER_ACCOUNT)
    .sort((a, b) => (a.meridianId < b.meridianId ? -1 : a.meridianId > b.meridianId ? 1 : 0))
    .map((c) => ({ companyId: c.meridianId, companyName: c.name }));
}

/**
 * Who at the account writes in.
 *
 * Weighted toward the people who actually use the product day to day: a dispatcher or ops
 * manager reports a broken board, not the CFO. Drawn from the account's real contacts, so the
 * sender is always somebody the CRM already knows.
 */
function pickContact(world: CrmWorld, companyId: string, rng: Rng): CrmContact {
  const theirs = world.contacts
    .filter((c) => c.companyMeridianId === companyId)
    .sort((a, b) => (a.meridianId < b.meridianId ? -1 : 1));
  if (theirs.length === 0) throw new Error(`no contact at ${companyId} to raise a support request`);
  const weight = (role: string): number =>
    role === "user" ? 5 : role === "champion" ? 4 : role === "it" ? 2 : 1;
  const pairs = theirs.map((c) => [c, weight(c.role)] as const);
  return rng.weighted(pairs);
}

/**
 * Which active incident, if any, causes this request.
 *
 * NO DRAW IS TAKEN WHEN THERE IS NOTHING TO DECIDE. If no incident is active, or none of the
 * affected accounts is currently eligible to write in, this returns null having consumed no Rng at
 * all -- so a world with no active incident produces exactly the stream it produced before
 * incidents existed. That is the same rule selectFamily states for itself ("Not drawing when there
 * is no choice matters for replay"), applied here for the same reason.
 *
 * ELIGIBILITY FIRST, PROBABILITY SECOND. The affected set is intersected with the accounts that
 * could legitimately raise a request right now -- current customers, with a contact, under the
 * open-request cap -- BEFORE the coin is tossed. An incident never reaches past the existing rules
 * to make an ineligible account write in.
 */
function pickCausingIncident(
  incidents: readonly CausingIncident[],
  eligible: readonly { companyId: string }[],
  rng: Rng,
): { incident: CausingIncident; accounts: { companyId: string }[] } | null {
  if (incidents.length === 0) return null;

  const eligibleIds = new Set(eligible.map((a) => a.companyId));
  const candidates = incidents
    .map((incident) => ({
      incident,
      accounts: eligible.filter((a) => incident.affectedCompanyIds.includes(a.companyId)),
    }))
    .filter((c) => c.accounts.length > 0 && c.incident.affectedCompanyIds.some((id) => eligibleIds.has(id)));
  if (candidates.length === 0) return null;

  // The coin. Half the time an eligible affected customer reports the fault; half the time this
  // request is an ordinary independent issue that happens to arrive during an incident.
  if (!rng.bool(INCIDENT_CAUSED_SHARE)) return null;

  // More than one capability broken at once is possible but rare. Uniform when it happens: ranking
  // them would assert that one fault is reported sooner than another, which nothing measures.
  return candidates.length === 1 ? candidates[0] : candidates[rng.int(0, candidates.length - 1)];
}

/**
 * Plan one inbound support request, or null when no account can raise one.
 *
 * Draw order is fixed: the causal coin (only when an incident could have caused this), then
 * account, contact, category (skipped when an incident forces it), then the three copy choices.
 * Reordering any of these re-rolls every value after it.
 *
 * TWO ORIGINS, ONE PLANNER. A request is either an independent customer issue or a report of an
 * active fault, and both come out of this function as the same shape. Splitting them into two
 * planners would have duplicated the account rules, the contact weighting and the copy pools --
 * and the whole point is that a caused request is an ORDINARY support email whose subject happens
 * to be determined by something real.
 */
export function planSupportRequest(
  world: CrmWorld,
  crm: LivingCrmState | null,
  support: LivingSupportState | null,
  rng: Rng,
  /** Incidents active at this instant. Empty, or omitted, means every request is independent. */
  activeIncidents: readonly CausingIncident[] = [],
): SupportRequestPlan | null {
  const accounts = eligibleSupportAccounts(world, crm, support);
  if (accounts.length === 0) return null;

  const caused = pickCausingIncident(activeIncidents, accounts, rng);

  // A caused request comes from an AFFECTED account; an independent one from any eligible account.
  const pool = caused ? caused.accounts : accounts;
  const account = pool.length === 1 ? pool[0] : pool[rng.int(0, pool.length - 1)];
  const resolved = accounts.find((a) => a.companyId === account.companyId)!;
  const contact = pickContact(world, resolved.companyId, rng);

  // Category frequency follows severity: most inbound mail is a question or a degraded
  // account, and a full dispatch outage is rare. Weighted so the inbox reads like a support
  // queue rather than a uniform sample of the taxonomy.
  //
  // FORCED, AND NO DRAW TAKEN, when an incident caused this. The customer is reporting the fault
  // that is actually happening, so the category IS the broken capability -- which is what makes the
  // visible email symptom match the incident family by construction rather than by assertion. A
  // draw here would let a dispatch outage surface as a data-export request.
  const category = caused
    ? caused.incident.capability
    : rng.weighted([
        ["configuration_help", 6],
        ["seat_change", 5],
        ["data_export", 4],
        ["data_import", 4],
        ["recurring_jobs", 3],
        ["exception_queue", 3],
        ["board_divergence", 2],
        ["dispatch_outage", 1],
      ] as const);
  const severity = SUPPORT_CATEGORIES[category];
  const copy = COPY[category];
  if (!copy) {
    // Only reachable if a capability were added without copy. Refused rather than rendering an
    // empty email, because a customer report with no prose is not a customer report.
    throw new Error(`no customer-voice copy for support category ${category}`);
  }

  const subject = rng.pick(copy.subject);
  const problem = rng.pick(copy.problem);
  const detail = rng.pick(copy.detail);

  const company = world.companies.find((c) => c.meridianId === resolved.companyId)!;
  const contactName = `${contact.firstName} ${contact.lastName}`;

  return {
    companyId: resolved.companyId,
    companyName: resolved.companyName,
    contactId: contact.meridianId,
    contactName,
    // Derived the way the frozen corpus derives it, never taken from the CRM's .com address.
    contactEmail: `${localPart(contactName)}@${customerDomain(company.domain)}`,
    category,
    severity,
    problem,
    subject,
    body: [
      "Hello,",
      problem.replace(/^The customer /, "We ").replace(/^An import/, "An import"),
      detail,
      "Thanks,",
      `${contact.firstName} ${contact.lastName}`,
      `${contact.jobTitle}, ${resolved.companyName}`,
    ].join("\n\n"),
    // Recorded, never rendered. Nothing above reads it; the prose comes entirely from the copy
    // pools, which contain no incident vocabulary because a customer does not know there is one.
    causedByIncidentId: caused ? caused.incident.incidentId : null,
  };
}

/**
 * The email as the mailbox holds it.
 *
 * Separated from planning so the rendering is a pure function of the plan plus the request id
 * and the receipt time -- which is what makes the persisted mail reproducible from the recorded
 * facts. The Message-ID comes from the frozen corpus's own helper, keyed on the request id
 * alone, so the same request always has the same message id from any call site.
 */
export function renderInboundEmail(
  plan: SupportRequestPlan,
  requestId: string,
  receivedAtMs: number,
  dateHeader: string,
): LivingInboundEmail {
  return {
    rfcMessageId: messageIdFor(requestId),
    from: { name: plan.contactName, email: plan.contactEmail },
    to: SUPPORT_INBOX,
    subject: plan.subject,
    dateHeader,
    body: plan.body,
  };
}
